1	package oci
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"net/http"
8		"net/http/httptest"
9		"reflect"
10		"strings"
11		"sync/atomic"
12		"testing"
13		"time"
14	)
15	
16	// DEVDESK-629 step 4 (F5, DEVDESK-633): a registry that does not answer before the
17	// client's delay ends the request with a *NoAnswerError whose text is "no answer
18	// within N s", N read from RequestTimeout. The delay itself is unchanged (15 s).
19	//
20	// None of these tests waits for it: a context already past its deadline, or a client
21	// swapped for one of tens of milliseconds against a server that blocks on its own
22	// request context, stands in for the real delay.
23	//
24	// This file names no symbol of the step (it detects the type by name), so it fails on
25	// an assertion before the code exists. The assertions that need the symbols
26	// (RequestTimeout, NoAnswerError) are in noanswer_symbols_test.go.
27	
28	// productionTimeout is the delay of the client as shipped, read before any test swaps it.
29	var productionTimeout = registryHTTPClient.Timeout
30	
31	// noAnswerText is the text a no-answer error must carry: the production delay, in whole
32	// seconds, never a literal.
33	func noAnswerText() string {
34		return fmt.Sprintf("no answer within %d s", int(productionTimeout/time.Second))
35	}
36	
37	// noAnswerIn reports whether err is, or wraps, a *NoAnswerError, and returns its text.
38	func noAnswerIn(err error) (string, bool) {
39		for e := err; e != nil; e = errors.Unwrap(e) {
40			if reflect.TypeOf(e).String() == "*oci.NoAnswerError" {
41				return e.Error(), true
42			}
43		}
44		return "", false
45	}
46	
47	// withClientTimeout swaps registryHTTPClient for a copy with another timeout, so the
48	// production CheckRedirect stays in force.
49	func withClientTimeout(t *testing.T, d time.Duration) {
50		t.Helper()
51		old := registryHTTPClient
52		c := *old
53		c.Timeout = d
54		registryHTTPClient = &c
55		t.Cleanup(func() { registryHTTPClient = old })
56	}
57	
58	const (
59		shortClientTimeout = 20 * time.Millisecond
60		slowHandlerCap     = time.Second
61	)
62	
63	// blockUntilGone holds a handler until the client has given up, with a cap so a missing
64	// timeout cannot hang the suite.
65	func blockUntilGone(r *http.Request) {
66		select {
67		case <-r.Context().Done():
68		case <-time.After(slowHandlerCap):
69		}
70	}
71	
72	// countingServer serves h and counts the requests it receives.
73	func countingServer(t *testing.T, h http.HandlerFunc) (*httptest.Server, *atomic.Int32) {
74		t.Helper()
75		var n atomic.Int32
76		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
77			n.Add(1)
78			h(w, r)
79		}))
80		t.Cleanup(srv.Close)
81		return srv, &n
82	}
83	
84	// registryCall is one way the client reads a registry.
85	type registryCall struct {
86		name string
87		run  func(ctx context.Context, apiURL string) error
88	}
89	
90	func registryCalls() []registryCall {
91		return []registryCall{
92			{"tags", func(ctx context.Context, u string) error {
93				_, err := ListRegistryTagsContext(ctx, u, "library/nginx", "", "")
94				return err
95			}},
96			{"catalog", func(ctx context.Context, u string) error {
97				_, _, err := ListCatalogContext(ctx, u, "", "", 3, 100)
98				return err
99			}},
100			{"catalog under a prefix", func(ctx context.Context, u string) error {
101				_, _, err := ListCatalogUnderContext(ctx, u, "docker-proxy", "", "", 3, 100)
102				return err
103			}},
104		}
105	}
106	
107	func expiredContext(t *testing.T) context.Context {
108		t.Helper()
109		ctx, cancel := context.WithDeadline(context.Background(), time.Now().Add(-time.Second))
110		t.Cleanup(cancel)
111		return ctx
112	}
113	
114	func wantNoAnswer(t *testing.T, err error) {
115		t.Helper()
116		if err == nil {
117			t.Fatal("err = nil, want a no-answer error")
118		}
119		text, ok := noAnswerIn(err)
120		if !ok {
121			t.Fatalf("err = %v (%T), want a *NoAnswerError", err, err)
122		}
123		if want := noAnswerText(); text != want {
124			t.Errorf("no-answer text = %q, want %q", text, want)
125		}
126		if !errors.Is(err, context.DeadlineExceeded) {
127			t.Errorf("errors.Is(err, context.DeadlineExceeded) = false for %v", err)
128		}
129		var se *StatusError
130		if errors.As(err, &se) {
131			t.Errorf("err carries a *StatusError (%v): no answer is not a status", se)
132		}
133	}
134	
135	func TestExpiredContextIsNoAnswer(t *testing.T) {
136		for _, c := range registryCalls() {
137			t.Run(c.name, func(t *testing.T) {
138				srv, hits := countingServer(t, func(w http.ResponseWriter, _ *http.Request) { w.WriteHeader(http.StatusOK) })
139	
140				wantNoAnswer(t, c.run(expiredContext(t), srv.URL))
141	
142				if n := hits.Load(); n != 0 {
143					t.Errorf("the registry received %d requests, want 0 for an expired context", n)
144				}
145			})
146		}
147	}
148	
149	// A registry that accepts the request and never answers, read through the real client
150	// delay (shrunk), for every call that reaches a registry, the manifest included.
151	func TestSlowRegistryIsNoAnswer(t *testing.T) {
152		calls := append(registryCalls(), registryCall{"manifest digest", func(_ context.Context, u string) error {
153			_, err := ManifestDigest(u, "library/nginx", "latest", "", "")
154			return err
155		}})
156		for _, c := range calls {
157			t.Run(c.name, func(t *testing.T) {
158				withClientTimeout(t, shortClientTimeout)
159				srv, hits := countingServer(t, func(_ http.ResponseWriter, r *http.Request) { blockUntilGone(r) })
160	
161				start := time.Now()
162				err := c.run(context.Background(), srv.URL)
163	
164				wantNoAnswer(t, err)
165				if n := hits.Load(); n == 0 {
166					t.Error("the registry received no request: the test did not exercise the client's delay")
167				}
168				if took := time.Since(start); took >= slowHandlerCap {
169					t.Errorf("returned after %v, want the client's own delay (%v)", took, shortClientTimeout)
170				}
171			})
172		}
173	}
174	
175	// The answer starts and stalls: the delay then ends the body read, not the request.
176	func TestSlowBodyIsNoAnswer(t *testing.T) {
177		stall := func(w http.ResponseWriter, r *http.Request) {
178			w.Header().Set("Content-Length", "1000")
179			_, _ = w.Write([]byte(`{"repositories":[`))
180			w.(http.Flusher).Flush()
181			blockUntilGone(r)
182		}
183		for _, c := range registryCalls() {
184			t.Run(c.name, func(t *testing.T) {
185				withClientTimeout(t, shortClientTimeout)
186				srv, _ := countingServer(t, stall)
187	
188				wantNoAnswer(t, c.run(context.Background(), srv.URL))
189			})
190		}
191	}
192	
193	// The token endpoint is a registry request too: one that never answers, or answers
194	// headers and stalls, is no answer.
195	func TestSlowTokenEndpointIsNoAnswer(t *testing.T) {
196		for name, token := range map[string]http.HandlerFunc{
197			"no answer": func(_ http.ResponseWriter, r *http.Request) { blockUntilGone(r) },
198			"stalled answer": func(w http.ResponseWriter, r *http.Request) {
199				w.Header().Set("Content-Length", "1000")
200				_, _ = w.Write([]byte(`{"token":`))
201				w.(http.Flusher).Flush()
202				blockUntilGone(r)
203			},
204		} {
205			t.Run(name, func(t *testing.T) {
206				withClientTimeout(t, shortClientTimeout)
207				srv := bearerRegistry(t, token, func(http.ResponseWriter, *http.Request) {})
208	
209				_, err := ListRegistryTagsContext(context.Background(), srv.URL, "library/nginx", "", "")
210	
211				wantNoAnswer(t, err)
212			})
213		}
214	}
215	
216	// A 502 that arrives in time is a status, not a lack of answer; its text says nothing
217	// about a delay, so the two cases cannot be confused.
218	func TestTimelyBadGatewayIsNotNoAnswer(t *testing.T) {
219		calls := append(registryCalls(), registryCall{"manifest digest", func(_ context.Context, u string) error {
220			_, err := ManifestDigest(u, "library/nginx", "latest", "", "")
221			return err
222		}})
223		for _, c := range calls {
224			t.Run(c.name, func(t *testing.T) {
225				srv, _ := countingServer(t, func(w http.ResponseWriter, _ *http.Request) { w.WriteHeader(http.StatusBadGateway) })
226	
227				err := c.run(context.Background(), srv.URL)
228	
229				var se *StatusError
230				if !errors.As(err, &se) || se.Code != http.StatusBadGateway {
231					t.Fatalf("err = %v (%T), want a *StatusError{502}", err, err)
232				}
233				if _, ok := noAnswerIn(err); ok {
234					t.Errorf("a 502 received in time is a no-answer error: %v", err)
235				}
236				if errors.Is(err, context.DeadlineExceeded) {
237					t.Errorf("a 502 received in time satisfies errors.Is(DeadlineExceeded): %v", err)
238				}
239				if strings.Contains(err.Error(), "no answer") {
240					t.Errorf("err text = %q, must not say no answer", err.Error())
241				}
242			})
243		}
244	}
245	
246	// The no-answer error is not a wrapper of the request: no URL, user, password or page
247	// size comes back with it.
248	func TestNoAnswerCarriesNoURL(t *testing.T) {
249		srv, _ := countingServer(t, func(w http.ResponseWriter, _ *http.Request) { w.WriteHeader(http.StatusOK) })
250		withCreds := strings.Replace(srv.URL, "http://", "http://alice:s3cr3t-pw@", 1)
251		host := strings.TrimPrefix(srv.URL, "http://")
252	
253		for _, c := range registryCalls() {
254			t.Run(c.name, func(t *testing.T) {
255				err := c.run(expiredContext(t), withCreds)
256	
257				wantNoAnswer(t, err)
258				for _, leak := range []string{"@", "alice", "s3cr3t", "http://", host, "n=", "/v2/"} {
259					if strings.Contains(err.Error(), leak) {
260						t.Errorf("err = %q carries %q", err.Error(), leak)
261					}
262				}
263			})
264		}
265	}
266	
267	// A cancellation is the caller's choice, not a lack of answer: it stays as it is.
268	func TestCancelledContextIsNotNoAnswer(t *testing.T) {
269		for _, c := range registryCalls() {
270			t.Run(c.name, func(t *testing.T) {
271				srv, _ := countingServer(t, func(w http.ResponseWriter, _ *http.Request) { w.WriteHeader(http.StatusOK) })
272				ctx, cancel := context.WithCancel(context.Background())
273				cancel()
274	
275				err := c.run(ctx, srv.URL)
276	
277				if !errors.Is(err, context.Canceled) {
278					t.Fatalf("err = %v, want errors.Is(context.Canceled)", err)
279				}
280				if _, ok := noAnswerIn(err); ok {
281					t.Errorf("a cancellation became a no-answer error: %v", err)
282				}
283			})
284		}
285	}
